# Generated by Sanka. Async FastAPI over the existing SQL tables.
from contextlib import asynccontextmanager

from fastapi import FastAPI, Request
from fastapi.responses import HTMLResponse, Response
from starlette.convertors import Convertor, register_url_convertor
from starlette.middleware.httpsredirect import HTTPSRedirectMiddleware
from starlette.middleware.trustedhost import TrustedHostMiddleware

import sanka_native as native
import sanka_store as store


@asynccontextmanager
async def lifespan(_app: FastAPI):
    await store.init_db()
    try:
        yield
    finally:
        await store.close_db()


app = FastAPI(title="Sanka native FastAPI application", lifespan=lifespan)

_DJANGO_DEFAULT_404 = "\n<!doctype html>\n<html lang=\"en\">\n<head>\n  <title>Not Found</title>\n</head>\n<body>\n  <h1>Not Found</h1><p>The requested resource was not found on this server.</p>\n</body>\n</html>\n"

@app.exception_handler(404)
async def django_default_404(_request: Request, _error: Exception) -> HTMLResponse:
    return HTMLResponse(_DJANGO_DEFAULT_404, status_code=404)

_HTTP_SECURITY = native.MANIFEST.get("http_security", {})
_ALLOWED_HOSTS = _HTTP_SECURITY.get("allowed_hosts", [])
if _HTTP_SECURITY.get("ssl_redirect"):
    app.add_middleware(HTTPSRedirectMiddleware)
if _ALLOWED_HOSTS and "*" not in _ALLOWED_HOSTS:
    app.add_middleware(TrustedHostMiddleware, allowed_hosts=_ALLOWED_HOSTS)

@app.middleware("http")
async def add_security_headers(request: Request, call_next):
    response = await call_next(request)
    native.apply_security_headers(response, request, _HTTP_SECURITY)
    return response

class _SankaAccountLookupConvertor(Convertor):
    regex = "[^/.]+"

    def convert(self, value: str) -> str:
        return value

    def to_string(self, value: str) -> str:
        return value


register_url_convertor("sanka_account_lookup", _SankaAccountLookupConvertor())

_ACCOUNT = native.resource("ledger.views.AccountViewSet")

@app.get("/api/")
async def api_root(request: Request) -> Response:
    return await native.api_root(request, "/api/")

@app.get("/api/accounts/")
async def list_account(request: Request) -> Response:
    return await native.handle(_ACCOUNT, "list", request)

@app.post("/api/accounts/")
async def create_account(request: Request) -> Response:
    return await native.handle(_ACCOUNT, "create", request)

@app.delete("/api/accounts/{pk:sanka_account_lookup}/")
async def delete_account(request: Request, pk: str) -> Response:
    return await native.handle(_ACCOUNT, "destroy", request)

@app.get("/api/accounts/{pk:sanka_account_lookup}/")
async def get_account(request: Request, pk: str) -> Response:
    return await native.handle(_ACCOUNT, "retrieve", request)

@app.patch("/api/accounts/{pk:sanka_account_lookup}/")
async def update_account(request: Request, pk: str) -> Response:
    return await native.handle(_ACCOUNT, "partial_update", request)

@app.put("/api/accounts/{pk:sanka_account_lookup}/")
async def replace_account(request: Request, pk: str) -> Response:
    return await native.handle(_ACCOUNT, "update", request)

# Routes outside Sanka's native envelope answer 501 with their
# adaptation codes: an unmigrated route fails loudly instead of
# silently 404ing. Replace each stub with a real handler; the
# inventory lives in sanka-manifest.json under unsupported_routes.

@app.api_route("/api/accounts/{pk}/transfer/", methods=["POST"])
async def sanka_unsupported() -> Response:
    return Response(
        content="{\"detail\":\"This route is outside Sanka's native generation envelope and has not been migrated.\",\"sanka\":{\"adaptation_codes\":[\"SANKA_DRF_CUSTOM_ACTION_UNSUPPORTED\"],\"route\":\"POST /api/accounts/{pk}/transfer/\",\"see\":\"sanka-manifest.json#unsupported_routes\"}}",
        status_code=501,
        media_type="application/json",
    )

